import java.util.*;
import java.io.*;
import java.math.*;

public class x440C {
    static long[] pow = new long[16];

    public static void main(String[] args) throws Exception {
        BufferedReader infile = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(infile.readLine());
        String input = st.nextToken();
        int N = input.length();
        int[] arr = new int[N];
        for (int i = 0; i < N; i++)
            arr[i] = Integer.parseInt(input.charAt(i) + "");
        pow[0] = 1L;
        for (int i = 1; i <= 15; i++)
            pow[i] = pow[i - 1] * 10;
        long start = Long.parseLong(input);
        System.out.println(solveIterative(start));
    }

    public static int solveIterative(long x) {
        // Use a stack to simulate recursion
        Deque<long[]> stack = new ArrayDeque<>();
        stack.push(new long[]{x, 0}); // {value, state} state 0 = not computed, 1 = computed
        Map<Long, Integer> results = new HashMap<>();
        while (!stack.isEmpty()) {
            long[] top = stack.peek();
            long val = top[0];
            if (val <= 11) {
                int base;
                if (val == 11) base = 2;
                else if (val == 10) base = 3;
                else if (val == 9) base = 4;
                else if (val == 8) base = 5;
                else if (val == 7) base = 6;
                else base = (int) val;
                results.put(val, base);
                stack.pop();
                continue;
            }
            if (top[1] == 1) {
                // already computed children, now compute result
                int len = Long.toString(val).length();
                long boof = 0;
                for (int i = 0; i <= len; i++)
                    boof += pow[i];
                int res = Integer.MAX_VALUE;
                if (val > boof - val)
                    res = Math.min(res, len + 1 + results.get(boof - val));
                boof -= pow[len];
                long firstDigit = val / pow[len - 1];
                for (int d = 1; d <= 9; d++) {
                    long candidate = boof * d;
                    if (d == firstDigit || d + 1 == firstDigit)
                        res = Math.min(res, len * d + results.get(Math.abs(candidate - val)));
                }
                results.put(val, res);
                stack.pop();
            } else {
                // push children
                top[1] = 1;
                int len = Long.toString(val).length();
                long boof = 0;
                for (int i = 0; i <= len; i++)
                    boof += pow[i];
                if (val > boof - val) {
                    long child = boof - val;
                    if (!results.containsKey(child))
                        stack.push(new long[]{child, 0});
                }
                boof -= pow[len];
                long firstDigit = val / pow[len - 1];
                for (int d = 1; d <= 9; d++) {
                    long candidate = boof * d;
                    if (d == firstDigit || d + 1 == firstDigit) {
                        long child = Math.abs(candidate - val);
                        if (!results.containsKey(child))
                            stack.push(new long[]{child, 0});
                    }
                }
            }
        }
        return results.get(x);
    }
}
